	@Test
	void completedFenceInvalidatesAConcurrentOlderSourceScan(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		Source source = new Source();
		source.rows.add(statement("first", 1));
		CountDownLatch scanEntered = new CountDownLatch(1);
		CountDownLatch releaseScan = new CountDownLatch(1);
		source.entered = scanEntered;
		source.release = releaseScan;
		source.pause.set(true);
		try (LmdbQuadSynopsisService service = service(source)) {
			service.configurePersistence(directory, false);
			service.requestRebuild();
			CompletableFuture<Boolean> built = new CompletableFuture<>();
			Thread worker = Thread.ofPlatform().daemon().name("fenced-source-scan").start(() -> {
				try {
					built.complete(service.forceFlush());
				} catch (Throwable failure) {
					built.completeExceptionally(failure);
				}
			});
			try {
				assertTrue(scanEntered.await(10, TimeUnit.SECONDS));
				var fence = service.beginStoreCommit();
				source.rows.add(statement("second", 2));
				fence.reconciled();
				releaseScan.countDown();
				assertFalse(built.get(20, TimeUnit.SECONDS), "a scan begun before the commit must not publish");
				assertFalse(service.isReadyNonBlocking());
				assertTrue(service.forceFlush());
				assertEquals(2.0d, rows(service));
			} finally {
				releaseScan.countDown();
				worker.join(TimeUnit.SECONDS.toMillis(20));
			}
		}
	}

